/**
 * General report inside an IDR, at /project/:projectId/idr/:idrId/general/:reportId.
 * Loads the parent IDR, uses this report's report_data as the form (report-specific fields only; the IDR's date,
 * times and weather show as a read-only context line), and Save Draft PUTs the whole form back
 * and then silently refetches the IDR. Submitting happens on the IDR page; once the IDR is submitted
 * (including mid-edit, detected by a 409 on save) the form renders read-only with a banner.
 * An auto-generated General is read-only too, with its own banner: a summary cover (Slice X.3), so its Pay Items,
 * Workforce and Equipment, and Safety Checks sections are replaced by a "See individual reports" note. A General that imported sites (migration 053's
 * backfill put an approved IDR's there) shows its Imported sites card read-only (Slice X): sites are imported on an
 * SWCB, but each links to its page, where its pay items for this IDR are entered.
 * Load / save / layout: useReportForm + ReportPageShell.
 */
import { useParams } from 'react-router-dom'
import useReportForm from '../../lib/useReportForm'
import { formDataFromReportData, sharedSectionDefaults } from '../../lib/reportData'
import ReportPageShell from '../../components/reports/ReportPageShell'
import DescriptionSection from '../../components/reports/DescriptionSection'
import PayItemsSection from '../../components/reports/PayItemsSection'
import WorkforceEquipmentCard from '../../components/reports/WorkforceEquipmentCard'
import SafetyChecklistSection from '../../components/reports/SafetyChecklistSection'
import CommentsSection from '../../components/reports/CommentsSection'
import ImportedSitesSection from '../../components/reports/ImportedSitesSection'
import useReportSites from '../../lib/useReportSites'
import useReportSitePayItems from '../../lib/useReportSitePayItems'

const AUTO_GENERATED_BANNER =
  'This General is auto-generated from your other reports. To change what appears here, edit the individual reports.'
export const SEE_INDIVIDUAL_REPORTS =
  'See individual reports: pay items, workforce and equipment, and safety checks are entered on each report.'
const DESCRIPTION_SUBHEADING =
  'Specify for Each Operation: Item No., Subcontractor (if any), Location, Nature of Work, Results and Details.'

// A blank General report. Only report-specific fields: date, times and weather come from the IDR.
function emptyFormData() {
  return {
    description: '',
    ...sharedSectionDefaults()
  }
}

export default function GeneralReportPage() {
  const { projectId, idrId, reportId } = useParams()
  const form = useReportForm({
    idrId,
    projectId,
    reportId,
    expectedReportType: 'GEN',
    emptyFormData,
    formDataFromReport: formDataFromReportData,
    isAutoGenType: true,
  })
  const { formData, isReadOnly, isAutoGenerated } = form
  const sites = useReportSites(idrId, reportId)
  const { sitePayItems } = useReportSitePayItems(idrId, reportId, sites.rows)
  const ignore = () => {}

  return (
    <ReportPageShell title="General Inspector's Report" autoGeneratedBannerText={AUTO_GENERATED_BANNER} form={form}>
      <DescriptionSection
        value={formData.description}
        onChange={(value) => form.handleInputChange('description', value)}
        subheading={DESCRIPTION_SUBHEADING}
        disabled={isReadOnly}
      />

      {/* Imported sites, read-only: shown once the report has some */}
      {(sites.status === 'error' || sites.rows.length > 0) && (
        <ImportedSitesSection form={{ ...form, isReadOnly: true }} sites={sites} onImported={ignore} onChanged={ignore}
          onRemoved={ignore} sitePayItems={sitePayItems} />
      )}

      {isAutoGenerated ? (
        // A summary cover: these sections live on the individual reports
        <div className="bg-white rounded-lg shadow-sm p-6 mb-6" data-testid="see-individual-reports">
          <h3 className="form-section-title">Pay Items, Workforce and Equipment, Safety Checks</h3>
          <p className="text-sm text-gray-600">{SEE_INDIVIDUAL_REPORTS}</p>
        </div>
      ) : (
        <>
          {/* Pay Items */}
          <PayItemsSection
            payItems={formData.payItems}
            onAddItem={form.addPayItem}
            onItemChange={form.handlePayItemChange}
            onRemoveItem={form.removePayItem}
            contractItems={form.contractItems}
            contractItemsLoading={form.contractItemsLoading}
            contractItemsError={form.contractItemsError}
            disabled={isReadOnly}
          />

          {/* Workforce and Equipment */}
          <WorkforceEquipmentCard form={form} />

          {/* Safety Checks */}
          <SafetyChecklistSection
            safetyChecks={formData.safetyChecks}
            onChange={form.handleSafetyCheckChange}
            remarks={formData.safetyRemarks}
            onRemarksChange={form.handleSafetyRemarksChange}
            disabled={isReadOnly}
          />
        </>
      )}

      {/* Comments */}
      <CommentsSection value={formData.comments} onChange={(v) => form.handleInputChange('comments', v)} disabled={isReadOnly} />
    </ReportPageShell>
  )
}
